const runs = Array.isArray(items) ? items.map(i => i.json) : [];
const complete = runs.filter(r => String(r.status) === 'complete').length;
const blocked = runs.filter(r => ['blocked','failed'].includes(String(r.status))).length;
const running = runs.filter(r => String(r.status) === 'running').length;
return [{json:{status:'ok', total:runs.length, complete, blocked, running, action: blocked > 0 ? 'notify_staff_placeholder' : complete > 0 ? 'timeline_finalize_placeholder' : 'no_op'}}];
